style.css:
@-moz-document domain("soundcloud.com") {
/* 01 - EMBEDDED 3D VECTOR LANDSCAPE + CRT SCANLINES
   True perspective floor, a wireframe mountain range and green sun.
   The SVG scene is embedded as data: URL; no external image requests.
   Background scales to viewport. The original theme colors are unchanged.
   For a less prominent scene, increase the black overlay opacity below. */
html,
body {
  background-color: #030905 !important;
  color: #8BFF9F !important;
}

body {
  background-image:
    linear-gradient(180deg, rgba(1, 7, 3, 0.32) 0%, rgba(1, 7, 3, 0.17) 48%, rgba(1, 7, 3, 0.32) 100%),
    url("data:image/svg+xml;base64,") !important;
  background-size: cover, cover !important;
  background-position: center center, center center !important;
  background-repeat: no-repeat, no-repeat !important;
  background-attachment: fixed, fixed !important;
  min-height: 100vh;
  font-family: "Courier New", Courier, monospace !important;
}

/* Extra faint horizon light; purely decorative, no click interception. */
body:before {
  content: "";
  position: fixed;
  top: 43%;
  left: 0;
  right: 0;
  height: 25vh;
  pointer-events: none;
  z-index: 0;
  opacity: 0.21;
  background-image: linear-gradient(180deg,
    transparent 0%, rgba(0, 255, 102, 0.10) 52%, transparent 100%);
}

/* Very fine, static horizontal CRT lines; no animations or blocked clicks. */
body:after {
  content: "";
  position: fixed;
  top: 0;
  right: 0;
  bottom: 0;
  left: 0;
  z-index: 2147483646;
  pointer-events: none;
  opacity: 0.30;
  background-image: repeating-linear-gradient(0deg,
    rgba(0, 0, 0, 0.0) 0px,
    rgba(0, 0, 0, 0.0) 2px,
    rgba(0, 0, 0, 0.32) 3px,
    rgba(0, 0, 0, 0.32) 4px);
}

#app,
#content,
.l-container,
.l-content,
.l-main {
  background-color: transparent !important;
}
#app { min-height: 100vh; }

/* 02 — HEADER, PLAYER, AND LOW SURFACES */
.header,
.header__inner,
.playControls,
.playControls__bg,
.playControls__inner,
.sound__soundActions,
.commentForm__wrapper,
.volume__sliderBackground {
  background-color: #07130C !important;
  color: #8BFF9F !important;
}

.header,
.playControls__inner {
  border-color: #276B42 !important;
  box-shadow: 0 2px 20px rgba(52, 255, 126, 0.16), 0 0 12px rgba(0, 255, 102, 0.16) !important;
}

/* 03 — RAISED CONTAINERS, MENUS, PANELS, MODALS */
.sc-background-light,
.sc-background-white,
.g-dark-bg,
.g-modal-section,
.modal__modal,
.dialog,
.dropbar__content,
.moreMenu__list,
.profileMenu__list,
.volume__sliderWrapper,
.tabs__tabs,
.tabs__headingContainer,
.listenLogin,
.uploadMain__foot,
.uploadMain__loggedOut,
.uploadMain__chooserContainer,
.commentFormDisabled,
.unreadConversations,
.audibleEditForm__form,
.gritter-item-wrapper,
.g-upsell-container,
.sidebarInfoBox,
.commentItem.m-creatorComment,
.l-fixed-top-one-column > .l-top,
#content > .container > .row,
#footer > .container > .row,
[role="dialog"],
[role="menu"],
[role="listbox"],
[role="tooltip"] {
  background-color: #0B1B11 !important;
  color: #8BFF9F !important;
}

.modal__modal,
.dialog,
.dropbar__content,
.moreMenu__list,
.profileMenu__list,
.sidebarInfoBox,
[role="dialog"],
[role="menu"],
[role="listbox"] {
  border: 1px solid #276B42 !important;
  box-shadow: 0 8px 30px rgba(0, 0, 0, 0.38),
              0 0 14px rgba(0, 255, 102, 0.16) !important;
}

.modal__modal,
.dialog {
  background-image: linear-gradient(155deg, #102619, #0B1B11 75%) !important;
}

.sidebarInfoBox {
  background-image: linear-gradient(145deg, rgba(0, 255, 102, 0.17), transparent 75%) !important;
}

.modal.modalWhiteout {
  background-color: rgba(1, 8, 3, 0.92) !important;
}

/* Volume popover pointer matches the raised panel. */
.volume__sliderWrapper:before,
.volume__sliderWrapper:after {
  border-top-color: transparent !important;
  border-right-color: transparent !important;
  border-bottom-color: #0B1B11 !important;
  border-left-color: #0B1B11 !important;
}

/* 04 — PHOSPHOR TEXT: mint-green in place of near-white */
/* Body text remains light enough to read over the brighter surfaces. */
body,
#content,
.l-content,
.l-main,
.sc-text,
.sc-text-primary,
.sc-type-medium,
.sc-type-small,
.commentItem__body,
.sound__mainContent,
.listenEngagement {
  color: #8BFF9F !important;
}

h1, h2, h3, h4, h5, h6,
.sc-type-h1,
.sc-type-h2,
.sc-type-h3,
.soundTitle__title,
.soundBadge__title,
.trackItem__trackTitle,
.audibleTile__title,
.g-type-shrinkwrap-large-primary,
.g-type-shrinkwrap-large-secondary {
  color: #59FF87 !important;
}

.sc-text-secondary,
.sc-text-light,
.soundTitle__username,
.soundBadge__username,
.soundTitle__uploadTime,
.commentBadge__time,
.sc-text-hint,
.sc-text-hint a,
.sc-ministats,
.commentItem__time {
  color: #57C77D !important;
}

.header__navMenu > li > a,
.g-dark a,
a.sc-link-light,
.header__login,
.header__upload {
  color: #8BFF9F !important;
}

.sc-text-link,
.staticPage p a,
.staticPage li a,
.commentItem a {
  color: #52FF8A !important;
}

.sc-text-link:hover,
.staticPage p a:hover,
.staticPage li a:hover,
.commentItem a:hover,
.g-dark a:hover,
a.sc-link-light:hover {
  color: #B8FFCA !important;
}

/* 04B — CONSISTENT GREEN TEXT IN COMMON SOUND/PLAYLIST LABELS */
body p,
body label,
body strong,
body li,
body small,
body time,
.sc-type-h3,
.sc-type-h4,
.sc-type-h5,
.sc-type-h6,
.soundBadge__title,
.soundBadge__username,
.playbackSoundBadge__titleLink,
.playbackSoundBadge__lightLink,
.playableTile__heading,
.playableTile__mainHeading,
.playableTile__username,
.userBadge__username,
.commentItem__username,
.commentItem__content,
.headerMenu__link,
.profileMenu__link,
.sideBar__section,
.sidebarModule__title {
  color: #8BFF9F !important;
}

a:not(.sc-button),
a:visited:not(.sc-button) {
  color: #6BFF99 !important;
}

/* 05 — TOP-LEFT SOUNDCLOUD LOGO: vivid green with soft neon glow */
/* Filter recolors a white, black, or image-backed logo without altering layout. */
.header__logoLink,
.header__logo > a,
header a[aria-label="SoundCloud"],
header a[title="SoundCloud"] {
  filter: brightness(0) saturate(100%) invert(68%) sepia(98%)
          saturate(1700%) hue-rotate(78deg) brightness(113%) contrast(115%)
          drop-shadow(0 0 7px rgba(0, 255, 102, 0.96))
          drop-shadow(0 0 19px rgba(0, 255, 102, 0.72)) !important;
}

/* Inline SVG logos are also covered when the logo is not image-backed. */
.header__logo svg,
.header__logoLink svg {
  fill: #00FF66 !important;
  color: #00FF66 !important;
}
.header__logo svg path,
.header__logoLink svg path,
.header__logo svg use,
.header__logoLink svg use {
  fill: #00FF66 !important;
}

/* 06 — NAVIGATION AND TABS */
.header__navMenu > li > a.selected,
.header__navMenu > li > a:hover,
.userNav__button.selected {
  background-color: #10291A !important;
  color: #B8FFCA !important;
}

.header__navMenu > li > a.selected,
.userNav__button.selected {
  border-bottom-color: #00FF66 !important;
}

.tabs__tab.active,
.tabs__tab:hover,
[role="tab"][aria-selected="true"] {
  color: #52FF8A !important;
  border-color: #00FF66 !important;
}

/* 07 — BUTTONS */
.sc-button {
  background-color: #11281A !important;
  color: #8BFF9F !important;
  border-color: #276B42 !important;
  transition: background-color 0.2s ease, color 0.2s ease,
              border-color 0.2s ease, box-shadow 0.2s ease !important;
}

.sc-button:hover {
  background-color: #1B3A25 !important;
  color: #B8FFCA !important;
  border-color: #52FF8A !important;
  box-shadow: 0 0 15px rgba(0, 255, 102, 0.26) !important;
}

.sc-button-selected,
.sc-button-active,
.sc-button[aria-pressed="true"] {
  border-color: #5CFF90 !important;
  color: #B8FFCA !important;
}

.sc-button-play,
.sc-button-cta {
  background-color: #0DEB5B !important;
  border-color: #0DEB5B !important;
  color: #030905 !important;
}

.sc-button-play:hover,
.sc-button-cta:hover {
  background-color: #ADFFBE !important;
  border-color: #B8FFCA !important;
  color: #030905 !important;
}

/* 08 — PLAYER, VOLUME, AND INTERACTIVE TRACKS */
.playbackTimeline__progressBackground,
.volume__sliderBackground,
.g-scrollbar,
.g-scrollbar-vertical {
  background-color: #10291A !important;
  border-color: #276B42 !important;
  box-shadow: none !important;
}

.playbackTimeline__progressBar,
.volume__sliderProgress {
  background-color: #27EE69 !important;
}

.playbackTimeline__progressHandle,
.volume__sliderHandle {
  background-color: #52FF8A !important;
}

.compactTrackListItem.clickToPlay:hover,
.chartTrack:hover,
.trackItem.hover,
.trackItem:hover,
[role="option"]:hover,
[role="menuitem"]:hover {
  background-color: #163320 !important;
}

.compactTrackListItem.clickToPlay.active,
.trackItem.active,
.editTrackItem.m-active,
[role="option"][aria-selected="true"] {
  background-color: #1A3A25 !important;
  border-left-color: #00FF66 !important;
}

.compactTrackList__moreLink,
.compactTrackList__moreLink:hover,
.moreActions__button,
.moreActions__group .moreActions__link {
  background-color: #10291A !important;
  color: #8BFF9F !important;
}

/* Keep hover overlays and overflow fades from becoming white. */
.soundBadge__additional,
.compactTrackListItem.clickToPlay:hover .compactTrackListItem__additional,
.compactTrackListItem.clickToPlay.active .compactTrackListItem__additional,
.truncatedUserDescription.m-overflow.m-collapsed .truncatedUserDescription__wrapper:after,
.truncatedAudioInfo.m-overflow.m-collapsed .truncatedAudioInfo__wrapper:after,
.trackItem.hover .trackItem__additional,
.trackItem.active .trackItem__additional,
.editTrackItem.m-active .editTrackItem__additional {
  background: transparent !important;
}

/* 09 — INPUTS, SEARCH, COMPOSERS */
input[type="text"],
input[type="search"],
input[type="email"],
input[type="password"],
input[type="url"],
input[type="number"],
textarea,
select,
.commentForm__input,
.composeTextfield .textfield__input,
.recipientChooser .tokenInput__wrapper,
.tokenInput__wrapper,
.headerSearch__input {
  background-color: #10291A !important;
  color: #8BFF9F !important;
  border-color: #276B42 !important;
}

input::placeholder,
textarea::placeholder {
  color: #479F64 !important;
}

input:focus,
textarea:focus,
select:focus,
a:focus,
button:focus {
  outline-color: #6BFF99 !important;
}

input:focus,
textarea:focus,
select:focus {
  border-color: #52FF8A !important;
  box-shadow: 0 0 0 2px rgba(0, 255, 102, 0.12) !important;
}

.sc-toggle,
.sc-toggle-handle,
.sc-radio-radio {
  background-color: #10291A !important;
  border-color: #276B42 !important;
}

/* 10 — TAGS AND SMALL INDICATORS */
.sc-tag {
  background-color: #0D2417 !important;
  color: #83FFA5 !important;
  border: 1px solid #2B7850 !important;
}

.sc-tag:hover {
  background-color: #173820 !important;
  color: #C9FFD4 !important;
}

.audibleTilePlaceholder:before {
  border-color: #276B42 !important;
}

/* 11 — SCROLLBARS (do NOT hide scrolling or site widgets) */
::-webkit-scrollbar { width: 10px; height: 10px; }
::-webkit-scrollbar-track { background-color: #030905; }
::-webkit-scrollbar-thumb {
  background-color: #24673E;
  border-radius: 8px;
  border: 2px solid #030905;
}
::-webkit-scrollbar-thumb:hover { background-color: #37F279; }

/* 12 - EMPTY STATES: native artwork left intact; icons tinted green */
.emptyNetworkPage__image,
.trackManager__noTracksImage,
.paging-eof:before {
  filter: grayscale(1) sepia(1) saturate(5) hue-rotate(71deg)
          brightness(0.80) drop-shadow(0 0 7px rgba(0, 255, 102, 0.22)) !important;
}

/* 13 — CONSISTENT HEADER ICONS, STATES, AND DROPDOWNS
   Color the controls without inverting avatars or artwork. Do not use a
   global SVG filter; mixed fill/stroke icons would become illegible. */
.header .header__navMenu > li > a,
.header .header__link,
.header .header__right a,
.header .header__right button,
.header .header__userNavUsernameButton,
.header .header__userNavActivitiesButton,
.header .header__userNavMessagesButton,
.header .header__userNavTipsButton,
.header .header__uiEvolutionButton,
.header .userNav__button,
.header .headerSearch__submit,
.header .notificationIcon {
  color: #85FF9D !important;
}

.header .header__right a:hover,
.header .header__right button:hover,
.header .header__navMenu > li > a:hover,
.header .header__userNavUsernameButton:hover,
.header .headerSearch__submit:hover,
.header .userNav__button:hover {
  color: #AAFFBA !important;
  background-color: #163320 !important;
}

.header .header__navMenu > li > a.selected,
.header .header__right a.selected,
.header .header__right button.selected,
.header .header__userNavUsernameButton.selected,
.header .userNav__button.selected {
  color: #B6FFC4 !important;
  background-color: #1C3A24 !important;
  border-bottom-color: #22FF77 !important;
}

/* Icons drawn with CSS sprites or pseudo-elements. */
.header .notificationIcon:before,
.header .notificationIcon:after,
.header .headerSearch__submit:before,
.header .headerSearch__submit:after,
.header .header__moreButton:before,
.header .header__moreButton:after,
.header .header__userNavActivitiesButton:before,
.header .header__userNavMessagesButton:before,
.header .header__userNavTipsButton:before {
  filter: brightness(0) saturate(100%) invert(68%) sepia(98%)
          saturate(1700%) hue-rotate(78deg) brightness(113%) contrast(115%) !important;
}

/* Inline SVGs using strokes or currentColor keep their internal shapes. */
.header a svg,
.header button svg,
.header .notificationIcon svg,
.header .headerSearch__submit svg {
  color: #85FF9D !important;
}

.header a:hover svg,
.header button:hover svg {
  color: #AAFFBA !important;
}

.header a svg [stroke],
.header button svg [stroke] {
  stroke: currentColor !important;
}

.header a svg [fill="currentColor"],
.header button svg [fill="currentColor"] {
  fill: currentColor !important;
}

/* Restore the separate green identity of the logo. */
.header .header__logoLink,
.header .header__logo > a {
  color: #00FF66 !important;
}
.header .header__logoLink svg,
.header .header__logo > a svg {
  color: #00FF66 !important;
  fill: #00FF66 !important;
}

/* Real menu classes, not just ARIA roles. */
.headerMenu,
.headerMenu.m-light,
.headerMenu__list,
.dropdownMenu,
.dropdownContent__container,
.searchAutocomplete,
.searchMenu,
.profileMenu,
.latestActivities__container,
.unreadConversations__container {
  background-color: #0B1B11 !important;
  color: #8BFF9F !important;
  border-color: #276B42 !important;
}

.headerMenu__link,
.dropdownContent__listItem,
.searchMenu__searchFor a,
.searchAutocomplete a,
.profileMenu a,
.moreMenu a,
.notifications a {
  color: #8BFF9F !important;
}

.headerMenu__link:hover,
.headerMenu__link:focus,
.dropdownContent__listItem:hover,
.searchMenu__searchFor a:hover,
.searchAutocomplete a:hover,
.profileMenu a:hover,
.moreMenu a:hover,
.notifications a:hover {
  color: #C6FFD2 !important;
  background-color: #1C3A26 !important;
}

.headerSearch__submit,
.headerSearch__input,
.headerSearch {
  border-color: #276B42 !important;
}

.newItemBadge,
.newItems__some {
  color: #D5FFE1 !important;
  background-color: #0E983D !important;
}

/* 14 — BOTTOM-PLAYER WAVEFORM-STYLE PROGRESS (CSS-ONLY)
   Uses a compact 160 x 22 px PNG waveform texture embedded in this CSS.
   This is not a real track's audio amplitude waveform. The site continues
   updating the played-width element, revealing more of the colored texture.
   No new elements, JavaScript, remote requests, or width overrides are used.
   Remove this section to restore the regular slim progress bar. */
.playbackTimeline__progressBackground,
.playbackTimeline__progressBar {
  height: 22px !important;
  margin-top: -10px !important;
  border: 0 !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  background-color: transparent !important;
  background-repeat: repeat-x !important;
  background-size: 160px 22px !important;
  background-position: left center !important;
}

.playbackTimeline__progressBackground {
  background-image: url("data:image/png;base64,") !important;
}

.playbackTimeline__progressBar {
  background-image: url("data:image/png;base64,") !important;
  filter: drop-shadow(0 0 3px rgba(0, 255, 102, 0.60)) !important;
  transition: width 0.10s linear !important;
}

.playbackTimeline__progressHandle {
  background-color: #70FF9E !important;
  border-color: #60FF92 !important;
  box-shadow: 0 0 6px rgba(0, 255, 102, 0.95),
              0 0 12px rgba(52, 255, 126, 0.60) !important;
}

.playbackTimeline__progressWrapper:hover .playbackTimeline__progressBar {
  filter: drop-shadow(0 0 5px rgba(52, 255, 126, 0.90)) !important;
}

/* 15 — MATCHING GREEN PLAYBACK, VOLUME, AND TRACK INDICATORS */
.volume__sliderProgress {
  background-color: #10E75A !important;
}
.volume__sliderHandle {
  background-color: #A0FFB6 !important;
  box-shadow: 0 0 8px rgba(52, 255, 126, 0.60) !important;
}
.playbackSoundBadge__titleLink:hover,
.soundTitle__title:hover,
.trackItem__trackTitle:hover {
  color: #99FFAB !important;
}


/* 16 — UNIFIED HOVER GLOW (PHOSPHOR / GREEN / MINT)
   Shadows only: no transforms, scaling, fixed positioning, or overlays.
   Keeps clicks, scrolling, and the site's own interactions intact. */

/* Transition interactive controls without applying filters to artwork. */
.header .header__navMenu > li > a,
.header .header__right a,
.header .header__right button,
.header .userNav__button,
.header .headerSearch__submit,
.headerMenu__link,
.profileMenu a,
.moreMenu a,
.dropdownContent__listItem,
.searchAutocomplete a,
.sc-button,
.sc-tag {
  transition: color 0.18s ease, background-color 0.18s ease,
              border-color 0.18s ease, box-shadow 0.18s ease,
              text-shadow 0.18s ease !important;
}

/* Header: phosphor green glow, matching menu icon/link states. */
.header .header__navMenu > li > a:hover,
.header .header__navMenu > li > a:focus,
.header .header__right a:hover,
.header .header__right a:focus,
.header .header__right button:hover,
.header .header__right button:focus,
.header .userNav__button:hover,
.header .userNav__button:focus,
.header .headerSearch__submit:hover,
.header .headerSearch__submit:focus {
  color: #CAFFD5 !important;
  background-color: #1C3D25 !important;
  border-color: #22FF77 !important;
  box-shadow: inset 0 -2px 0 #22FF77,
              0 0 11px rgba(0, 255, 102, 0.48),
              0 0 22px rgba(52, 255, 126, 0.16) !important;
  text-shadow: 0 0 8px rgba(115, 255, 160, 0.58) !important;
}

/* The brand logo stays neon green. */
.header .header__logoLink:hover,
.header .header__logoLink:focus,
.header .header__logo > a:hover,
.header .header__logo > a:focus {
  background-color: transparent !important;
  border-color: transparent !important;
  box-shadow: none !important;
  filter: brightness(0) saturate(100%) invert(68%) sepia(98%)
          saturate(1700%) hue-rotate(78deg) brightness(113%) contrast(115%)
          drop-shadow(0 0 7px rgba(0, 255, 102, 0.96))
          drop-shadow(0 0 19px rgba(0, 255, 102, 0.72)) !important;
}

/* Menus and small clickable items: green inset edge and soft mint aura. */
.headerMenu__link:hover,
.headerMenu__link:focus,
.profileMenu a:hover,
.profileMenu a:focus,
.moreMenu a:hover,
.moreMenu a:focus,
.dropdownContent__listItem:hover,
.dropdownContent__listItem:focus,
.searchAutocomplete a:hover,
.searchAutocomplete a:focus,
[role="menuitem"]:hover,
[role="menuitem"]:focus,
[role="option"]:hover,
[role="option"]:focus {
  background-color: #193D27 !important;
  color: #CAFFD5 !important;
  box-shadow: inset 3px 0 0 #22FF77,
              inset 0 0 14px rgba(52, 255, 126, 0.16),
              0 0 11px rgba(0, 255, 102, 0.20) !important;
}

/* Standard actions: blended green + green, no size change. */
.sc-button:hover,
.sc-button:focus {
  border-color: #22FF77 !important;
  box-shadow: 0 0 0 1px rgba(0, 255, 102, 0.35),
              0 0 12px rgba(0, 255, 102, 0.38),
              0 0 23px rgba(0, 255, 102, 0.14) !important;
  text-shadow: 0 0 7px rgba(115, 255, 160, 0.38) !important;
}

/* Primary play and call-to-action controls: hotter green outer glow. */
.sc-button-play:hover,
.sc-button-play:focus,
.sc-button-cta:hover,
.sc-button-cta:focus {
  border-color: #8BFF9F !important;
  box-shadow: 0 0 0 1px rgba(52, 255, 126, 0.70),
              0 0 14px rgba(0, 255, 102, 0.75),
              0 0 27px rgba(0, 255, 102, 0.34) !important;
  text-shadow: none !important;
}

/* Tracks: gentle mint/green edge so lists do not turn into neon boxes. */
.trackItem:hover,
.compactTrackListItem.clickToPlay:hover,
.chartTrack:hover,
.soundBadge:hover {
  background-color: #142E1C !important;
  box-shadow: inset 3px 0 0 #22FF77,
              0 0 12px rgba(52, 255, 126, 0.17) !important;
}

/* Hovered links glow without a visible outline around entire text blocks. */
.sc-text-link:hover,
.commentItem a:hover,
.trackItem__trackTitle:hover,
.soundTitle__title:hover,
.playbackSoundBadge__titleLink:hover {
  color: #B1FFC3 !important;
  text-shadow: 0 0 9px rgba(0, 255, 102, 0.43) !important;
}

/* Search and forms: illuminate the border, not the whole input surface. */
.headerSearch__input:hover,
input[type="search"]:hover,
input[type="text"]:hover,
textarea:hover {
  border-color: #38DF79 !important;
  box-shadow: 0 0 9px rgba(0, 255, 102, 0.17) !important;
}

.headerSearch__input:focus,
input[type="search"]:focus,
input[type="text"]:focus,
