.soundBadge__artwork,
.audibleTile__artwork,
.visualSound__artwork,
.tileGallery .sc-artwork {
  transition: box-shadow 0.22s ease, outline-color 0.22s ease !important;
}

/* The artwork link is the safest outer anchor for the square glow. */
.playableTile:hover .playableTile__artworkLink,
.playableTile__artworkLink:hover,
.playableTile__artworkLink:focus,
.playableTile:hover .playableTile__artwork,
.playableTile__artwork:hover,
.playableTile__artworkLink:hover .sc-artwork,
.playableTile__artworkLink:focus .sc-artwork,
.tileGallery__sliderPanelSlide:hover .playableTile__artworkLink,
.soundBadge:hover .soundBadge__artwork,
.soundBadge__artwork:hover,
.audibleTile:hover .audibleTile__artwork,
.visualSound:hover .visualSound__artwork {
  border-radius: 5px !important;
  box-shadow: 0 0 0 2px #22FF77,
              0 0 13px rgba(0, 255, 102, 0.82),
              0 0 27px rgba(115, 255, 160, 0.55) !important;
}

/* Keep genre and album captions visually coordinated on hover. */
.playableTile:hover .playableTile__heading,
.playableTile:hover .playableTile__mainHeading,
