/* 19 - PHOSPHOR TERMINAL TYPOGRAPHY AND EDGE DETAILS */
.header,
.headerMenu,
.profileMenu,
.moreMenu,
.tabs__tabs,
.playControls__inner,
.sc-button,
input,
textarea,
select {
  font-family: "Courier New", Courier, monospace !important;
}

.header,
.playControls__inner,
.modal__modal,
.dialog,
.sidebarInfoBox {
  border-color: #276B42 !important;
  box-shadow: 0 0 0 1px rgba(0, 255, 102, 0.18),
              0 0 20px rgba(0, 255, 102, 0.12) !important;
}

/* Retain light outlines on the header without tinting cover art. */
.header .header__navMenu > li > a:hover,
.header .userNav__button:hover,
.header .header__right a:hover,
.headerMenu__link:hover,
.profileMenu a:hover {
  text-shadow: 0 0 7px rgba(0, 255, 102, 0.85) !important;
}

/* Green soundbar and volume HUD. */
.playbackTimeline__progressHandle,
.volume__sliderHandle {
