}

/* Content panels stay dark, leaving the vector grid visible in the gutters. */
.sc-background-light,
.sc-background-white,
[role="dialog"],
[role="menu"] {
  background-color: #0B1B11 !important;
}

/* 20 - TRANSLUCENT PHOSPHOR GLASS / VECTOR LANDSCAPE DEPTH
   A subtle 14-18% view of the 3D wireframe landscape through panels.
   Change only background COLOR alpha, never opacity on whole elements:
   artwork, text, buttons, and playback controls remain fully opaque.
   No blur is used, to keep the vector grid visibly sharp. */

/* Main feed cards, collection surfaces, tabs, sidebars and content panels. */
.sc-background-light,
.sc-background-white,
.g-dark-bg,
.g-modal-section,
.tabs__tabs,
.sidebarInfoBox,
.commentItem.m-creatorComment,
.l-fixed-top-one-column > .l-top,
#content > .container > .row,
#footer > .container > .row,
.soundList__item,
.listenLogin,
.uploadMain__foot,
.uploadMain__loggedOut,
.uploadMain__chooserContainer,
.commentFormDisabled,
.unreadConversations,
.audibleEditForm__form,
.gritter-item-wrapper,
.g-upsell-container {
  background-color: rgba(5, 24, 12, 0.82) !important;
}

/* Feed/article wrappers: avoid painting another opaque layer over cards. */
.sound__content,
.sound__mainContent,
.tabs__headingContainer {
  background-color: transparent !important;
}

/* Header + pinned player get a little more contrast around their controls. */
.header,
.header__inner,
.playControls,
.playControls__bg,
.playControls__inner,
.volume__sliderBackground {
  background-color: rgba(3, 16, 8, 0.91) !important;
}

/* Floating dropdowns and contextual menus remain readable but translucent. */
.modal__modal,
.dialog,
.dropbar__content,
.moreMenu__list,
.profileMenu__list,
.profileMenu,
.headerMenu,
.headerMenu.m-light,
.dropdownMenu,
.dropdownContent__container,
.searchAutocomplete,
.searchMenu,
.latestActivities__container,
.unreadConversations__container,
.volume__sliderWrapper,
[role="dialog"],
[role="menu"],
[role="listbox"],
[role="tooltip"] {
  background-color: rgba(4, 20, 10, 0.86) !important;
}

/* The list inside a menu should not create a second, opaque layer. */
.headerMenu__list {
  background-color: transparent !important;
}

/* Old opaque modal gradients must also become translucent. */
.modal__modal,
.dialog {
  background-image: linear-gradient(155deg,
    rgba(13, 42, 22, 0.84),
    rgba(4, 20, 10, 0.86) 75%) !important;
}

/* Let the scenic layer show through the comment action strips too. */
.commentForm__wrapper,
.sound__soundActions {
  background-color: rgba(5, 23, 12, 0.84) !important;
}

/* Preserve the original fluorescent edges instead of relying on fill. */
.soundList__item,
.sidebarInfoBox,
.modal__modal,
.dialog,
.moreMenu__list,
.profileMenu__list,
.headerMenu,
.dropdownMenu {
  border-color: rgba(52, 255, 126, 0.32) !important;
}

/* 21 - COMPLETE LAYOUT GLASS: FEED SIDEBAR + DISCOVERY + LIBRARY
   Addresses opaque/unframed page shells left behind by v1.2.
   IMPORTANT: Never use opacity on containers: that fades the cover art.
   Only RGBA background colors are translucent. The 3D body layer stays fixed.

   Target coverage:
   - Right sidebar on Following/Feed and listening views
   - Discover/listening recommendations and horizontally scrolling tile lanes
   - Library / collection content and scrollable album sections
   - Related sidebar modules, without stacking multiple dark fills
*/

/* The right rail needs its OWN glass surface, independently of the feed. */
.l-sidebar-right,
.l-fluid-fixed .l-sidebar-right,
.l-three-column .l-sidebar-right,
.l-listen-wrapper .l-sidebar-right {
  background-color: rgba(3, 22, 11, 0.72) !important;
  background-image: none !important;
  border-left: 1px solid rgba(45, 255, 112, 0.23) !important;
  box-shadow: inset 1px 0 14px rgba(0, 255, 102, 0.05) !important;
}

/* Avoid double-darkening: components nested inside the sidebar share its glass. */
.l-sidebar-right .sidebarInfoBox,
.l-sidebar-right .sidebarModule,
.l-sidebar-right .sidebarModule__content,
.l-sidebar-right .sidebarModule__inner,
.l-sidebar-right .sidebarHeader,
.l-sidebar-right .whoToFollowModule,
.l-sidebar-right .likesModule,
.l-sidebar-right .soundLikesModule,
.l-sidebar-right .soundRepostsModule,
.l-sidebar-right .soundInSetsModule,
.l-sidebar-right .relatedTracks,
.l-sidebar-right .streamSidebar,
.l-sidebar-right .l-footer {
  background-color: transparent !important;
  background-image: none !important;
}

/* Discover and Library use separate scrollable page shells. Apply a single
   translucent surface to the available route or content wrapper. */
.l-listen-wrapper .l-main,
.l-discover .l-main,
.l-library .l-main,
.l-collection .l-main,
.listenContent__inner,
.listenNetworkTop__inner,
.collection,
.collection__content {
  background-color: rgba(3, 21, 10, 0.67) !important;
  background-image: none !important;
}

/* A page shell already supplies the tint: its nested wrappers stay clear. */
.l-listen-wrapper .listenContent__inner,
.l-listen-wrapper .listenNetworkTop__inner,
.l-discover .listenContent__inner,
.l-library .collection,
.l-library .collection__content,
.l-collection .collection,
.l-collection .collection__content,
.collection .collection__content {
  background-color: transparent !important;
  background-image: none !important;
}

/* Scrolling carousels and collection rows should not insert opaque bands. */
.listenContent__inner .tileGallery,
.listenContent__inner .tileGallery__slider,
.listenContent__inner .tileGallery__sliderPanel,
.listenContent__inner .tileGallery__sliderPanelSlide,
.collection .collection__section,
.collection .collection__sectionContent,
.collection .collection__main,
.collection .collection__oneRowSection,
.collection .collectionSection,
.collection .collectionSection__content,
.collection .collectionSection__main,
.collection .tileGallery,
.collection .tileGallery__slider,
.collection .tileGallery__sliderPanel,
.collection .tileGallery__sliderPanelSlide,
.l-main .g-scrollable-inner {
  background-color: transparent !important;
}

/* If a bright generic SoundCloud surface is placed inside Discovery/Library,
   retain the glass rather than reverting to an opaque site-default fill. */
.l-listen-wrapper .sc-background-light,
.l-listen-wrapper .sc-background-white,
.l-library .sc-background-light,
.l-library .sc-background-white,
.l-collection .sc-background-light,
.l-collection .sc-background-white,
.collection .sc-background-light,
.collection .sc-background-white {
  background-color: rgba(5, 24, 12, 0.35) !important;
}

/* Right-column lists, buttons, artwork and text keep opacity: 1 by default. */

/* ==============================================================
   22. DISCOVER RECOMMENDATION SHELVES - INDIVIDUAL GREEN GLASS
   https://soundcloud.com/discover

   v1.3 covered the listening and collection wrappers. Discover also
   renders mixed-selection shelves, system playlists, and dynamically
   appended discovery modules that aren't inside those wrappers.

   Tint the actual section surfaces with alpha backgrounds, rather
   than applying opacity to an ancestor (which fades cover artwork).
   ============================================================== */

/* The outer Discover canvas gets a light smoked-glass wash so there
   is contrast even between individual horizontal recommendation rows. */
#content .l-content,
#content .l-fixed-top,
#content .l-fixed-top-one-column {
  background-color: rgba(2, 18, 9, 0.27) !important;
}

/* Discover's repeated shelves: each gets its own visible translucent
   layer rather than an opaque band or fully transparent canvas. */
.discovery__module,
.discoveryModule,
.mixedSelectionModule,
.systemPlaylistBannerItem,
.lazyLoadingList__list > .discoveryModule,
.lazyLoadingList__list > .mixedSelectionModule,
.discoverMain__module,
.discoverModule {
  background-color: rgba(3, 24, 12, 0.74) !important;
  background-image: none !important;
  border-radius: 8px !important;
  box-shadow: inset 0 0 0 1px rgba(48, 255, 115, 0.14),
              0 1px 16px rgba(0, 255, 102, 0.04) !important;
}

/* Parent wrappers receive only a light wash; this avoids stacking
   multiple opaque-looking panels over the 3D scene. */
.discovery,
.discovery__content,
.discovery__section,
.discovery__main,
.discoverMain__content,
.discoverMain__section,
.mixedSelectionModule__wrapper {
  background-color: rgba(3, 24, 12, 0.14) !important;
  background-image: none !important;
}

/* When the Discover module itself is a wrapper around a shelf, keep
   the tiles and scrollable track strips optically clear. */
.discoveryModule .tileGallery,
.discoveryModule .tileGallery__slider,
.discoveryModule .tileGallery__sliderPanel,
.discoveryModule .tileGallery__sliderPanelSlide,
.discoveryModule .tileGallery__content,
.discoveryModule .tileGallery__list,
.mixedSelectionModule .tileGallery,
.mixedSelectionModule .tileGallery__slider,
.mixedSelectionModule .tileGallery__sliderPanel,
.mixedSelectionModule .tileGallery__sliderPanelSlide,
.discovery__module .tileGallery,
.discovery__module .tileGallery__slider,
.discovery__module .tileGallery__sliderPanel,
.discovery__module .tileGallery__sliderPanelSlide,
.discovery__module .sc-background-white,
.discovery__module .sc-background-light,
.discoveryModule .sc-background-white,
.discoveryModule .sc-background-light,
.mixedSelectionModule .sc-background-white,
.mixedSelectionModule .sc-background-light,
.discoveryModule .g-scrollable-inner,
.mixedSelectionModule .g-scrollable-inner {
  background-color: transparent !important;
  background-image: none !important;
}

/* Specifically covers the horizontal Discover recommendation strips,
   including dynamically loaded grid/trending groups.  Applies only
   when inside the known Discover wrappers; no universal element tint. */
.discovery__module .mixedSelectionModule,
.discovery__module .discoveryModule,
.discoveryModule .mixedSelectionModule,
.mixedSelectionModule .mixedSelectionModule__content,
.discoveryModule .discoveryModule__content,
.discovery__module .discovery__content {
  background-color: rgba(4, 25, 13, 0.22) !important;
  background-image: none !important;
}

/* Leave artwork, play buttons, cover overlays and glyphs fully opaque.
   There is intentionally no CSS opacity property on these containers. */

/* ==============================================================
   23. CLASSIC CRT TERMINAL TYPOGRAPHY
   Lucida Console is the primary Windows fallback: compact, rigid,
   and reminiscent of old monitors. No remote font downloads.
   Important: no universal '*' override so icon font glyphs survive.
   ============================================================== */
body,
#content,
.l-content,
.l-main,
.header,
.header__navMenu > li > a,
.header__search,
.headerSearch__input,
.headerMenu,
.profileMenu,
.moreMenu,
.moreMenu__list,
.profileMenu__list,
.tabs__tabs,
.playControls__inner,
.sc-button,
button,
input,
textarea,
select,
.sc-text,
.sc-text-primary,
.sc-text-secondary,
.sc-text-light,
.sc-text-hint,
.commentItem__body,
.sc-type-medium,
.sc-type-small,
.sc-type-h1,
.sc-type-h2,
.sc-type-h3,
.soundTitle__title,
.soundBadge__title,
.trackItem__trackTitle,
.audibleTile__title,
.playbackTimeline__timePassed,
.playbackTimeline__duration {
  font-family: "Lucida Console", "Cascadia Mono", Consolas, "Courier New", monospace !important;
}

/* Slight tracking conveys the phosphor-terminal feel without altering
   tile sizes or letter spacing within branding graphics. */
#content,
.header__navMenu > li > a,
.headerMenu,
.profileMenu,
.tabs__tabs,
.sc-button,
input,
textarea,
select {
  letter-spacing: 0.12px !important;
}

/* Keep headers brighter but not oversized; compensate for the
   relatively narrow uppercase-ish terminal character shapes. */
.discoveryModule h2,
.mixedSelectionModule h2,
.discovery__module h2,
.collection h2,
.sc-type-h2,
.sc-type-h3 {
  text-shadow: 0 0 8px rgba(0, 255, 102, 0.18) !important;
}

/* 24 - MAIN TRACK / PLAYLIST WAVEFORM: GREEN PLAYED BARS
   SoundCloud paints the tall waveform in canvases (separate from the
   small bottom playback timeline).  Shift its native orange to phosphor
   green while keeping bright unplayed bars bright.  The comments canvas
   is intentionally excluded to avoid recoloring its overlay and labels.
   No changes to waveform dimensions, timing, interaction, or artwork. */
.waveform .waveform__layer canvas:not(.waveformCommentsNode),
.sound__waveform .waveform__layer canvas:not(.waveformCommentsNode),
.waveform .waveform__layer > img,
.waveform .waveform__layer > picture img {
  -webkit-filter: hue-rotate(130deg) saturate(120%) brightness(140%) !important;
  filter: hue-rotate(130deg) saturate(120%) brightness(140%) !important;
}

/* Fallback for SoundCloud waveform variants with a played-color layer
   instead of a canvas or image.  This does not target user avatars. */
.waveform .waveform__layer--played,
.sound__waveform .waveform__layer--played {
  -webkit-filter: hue-rotate(130deg) saturate(120%) brightness(140%) !important;
  filter: hue-rotate(130deg) saturate(120%) brightness(140%) !important;
}
}
